    "context": "Crônicas conta novamente o episódio de Gibeom, já relatado em 1 Reis 3, mas com ênfase própria: aqui Salomão vai a Gibeom acompanhado por toda a assembleia de Israel, diante da tenda do encontro e do altar de bronze feito por Bezalel no deserto, ligando explicitamente seu reinado à herança do tabernáculo mosaico. Assim como em Reis, Deus concede sabedoria, mas Crônicas destaca ainda mais a riqueza e a honra concedidas, coerente com o interesse do cronista em mostrar a glória do reinado de Salomão como reflexo da bênção de Deus.",
