          "text": "Então o rei disse ao homem de Deus: \"Interceda junto ao Senhor, o seu Deus, e ore por mim para que meu braço se recupere\". O homem de Deus intercedeu junto ao Senhor, e o braço do rei recuperou-se e voltou ao normal."
