          "text": "Ora, Elias, o tesbita da Tisbe de Gileade, disse a Acabe: \"Juro pelo nome do Senhor, o Deus de Israel, a quem sirvo, que não cairá orvalho nem chuva nos anos seguintes, exceto mediante a minha palavra\"."
