          "n": 12,
          "text": "\"Juro pelo nome do Senhor, o teu Deus\", ela respondeu, \"não tenho nenhum pedaço de pão; só um punhado de farinha num jarro e um pouco de azeite numa botija. Estou colhendo uns dois gravetos para levar para casa e preparar uma refeição para mim e para o meu filho, para que a comamos e depois morramos. \""
