          "text": "E ele respondeu aos mensageiros de Ben-Hadade: \"Digam ao rei, meu senhor: Teu servo fará tudo o que exigiste na primeira vez, mas não posso atender a esta exigência\". E eles levaram a resposta a Ben-Hadade."
