          "text": "Ele respondeu-lhe: \"Porque eu disse a Nabote, de Jezreel: Venda-me a sua vinha; ou, se preferir, eu lhe darei outra vinha em lugar dessa. Mas ele disse: ‘Não te darei minha vinha’ \"."
